using System;using System.IO;using System.Net;using System.Text;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.Threading;using System.Web.Script.Serialization;
// Isolated read-only probe: no refresh POSTs, credential writes, raw body logs or polling.
public static class Probe {
 public const int Cap=524288;
 static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=Cap,RecursionLimit=24};
 static string[] Urls={"https://chatgpt.com/backend-api/wham/profiles/me","https://api.anthropic.com/api/oauth/usage","https://cli-chat-proxy.grok.com/v1/billing?format=credits"};
 public class Bad:Exception{public Bad(string c):base(c){}}
 public class Reply{public int Http,Bytes;public string Body,Error;}
 static object F(Dictionary<string,object>d,string k){object v;return d.TryGetValue(k,out v)?v:null;}
 static Dictionary<string,object> D(object x){var d=x as Dictionary<string,object>;if(d==null)throw new Bad("schema_object");return d;}
 public static Dictionary<string,object> Parse(string s){if(s==null||Encoding.UTF8.GetByteCount(s)>Cap)throw new Bad("response_too_large");try{return D(J.DeserializeObject(s));}catch(Bad){throw;}catch{throw new Bad("invalid_json");}}
 public static long Integer(object x){if(x is int &&(int)x>=0)return(int)x;if(x is long &&(long)x>=0)return(long)x;if(x is decimal){decimal n=(decimal)x;if(n>=0&&n<=long.MaxValue&&n==Decimal.Truncate(n))return(long)n;}throw new Bad("invalid_integer");}
 static double Percent(object x){if(!(x is int||x is long||x is decimal||x is double))throw new Bad("invalid_percent");double n=Convert.ToDouble(x,CultureInfo.InvariantCulture);if(Double.IsNaN(n)||Double.IsInfinity(n)||n<0||n>1000)throw new Bad("invalid_percent");return n;}
 public static Dictionary<string,object> Codex(string text){var s=D(F(Parse(text),"stats"));var r=new Dictionary<string,object>();object life=F(s,"lifetime_tokens");r["lifetime_tokens"]=life==null?null:(object)Integer(life);object raw=F(s,"daily_usage_buckets");var a=raw as object[];if(raw!=null&&a==null)throw new Bad("schema_array");r["daily_buckets"]=a==null?null:(object)a.Length;if(a==null)return r;if(a.Length>4000)throw new Bad("too_many_records");var seen=new HashSet<string>();long sum=0;string first=null,last=null;foreach(object row in a){var d=D(row);string date=F(d,"start_date")as string;DateTime dt;if(date==null||!DateTime.TryParseExact(date,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out dt))throw new Bad("invalid_date");if(!seen.Add(date))throw new Bad("duplicate_date");try{sum=checked(sum+Integer(F(d,"tokens")));}catch(OverflowException){throw new Bad("integer_overflow");}if(first==null||String.CompareOrdinal(date,first)<0)first=date;if(last==null||String.CompareOrdinal(date,last)>0)last=date;}r["daily_buckets_sum"]=sum;r["first_date"]=first;r["last_date"]=last;return r;}
 public static Dictionary<string,object> Claude(string text){var d=Parse(text);var r=new Dictionary<string,object>();foreach(string k in new[]{"five_hour","seven_day"}){object w=F(d,k);if(w==null)continue;var v=D(w);if(F(v,"utilization")==null)throw new Bad("usage_missing");r[k+"_used_percent"]=Percent(F(v,"utilization"));}if(r.Count==0)throw new Bad("usage_missing");r["whole_account_token_history"]=false;return r;}
 public static Dictionary<string,object> Grok(string text){var d=D(F(Parse(text),"config"));var r=new Dictionary<string,object>();if(F(d,"creditUsagePercent")!=null)r["used_percent"]=Percent(F(d,"creditUsagePercent"));object raw=F(d,"history");var a=raw as object[];if(raw!=null&&a==null)throw new Bad("schema_array");r["history_records"]=a==null?null:(object)a.Length;if(a!=null){if(a.Length>4000)throw new Bad("too_many_records");int count=0;foreach(object row in a){var b=D(row);foreach(string k in new[]{"includedUsed","onDemandUsed","totalUsed"})if(F(b,k)!=null){Integer(F(D(F(b,k)),"val")??0);count++;}}r["history_amount_fields"]=count;}if(F(d,"prepaidBalance")!=null)r["prepaid_usd_cents"]=Integer(F(D(F(d,"prepaidBalance")),"val")??0);r["unit"]="credit_or_usd_cents_not_tokens";return r;}
 static string Home(string env,string fallback){string s=Environment.GetEnvironmentVariable(env);return String.IsNullOrWhiteSpace(s)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),fallback):s.Trim();}
 static Dictionary<string,object> ReadAuth(string p){try{using(var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(f.Length>65536)throw new Bad("credential_too_large");using(var m=new MemoryStream()){byte[] b=new byte[4096];int n;while((n=f.Read(b,0,b.Length))>0){if(m.Length+n>65536)throw new Bad("credential_too_large");m.Write(b,0,n);}return Parse(new UTF8Encoding(false,true).GetString(m.ToArray()));}}}catch(Bad){throw;}catch{throw new Bad("credential_unavailable");}}
 public static Reply Fetch(string url,Dictionary<string,string> headers,int deadline,bool testOnly){var r=new Reply();Uri u;bool valid=Uri.TryCreate(url,UriKind.Absolute,out u);bool allow=valid&&Array.IndexOf(Urls,url)>=0;if(!allow&&!(testOnly&&valid&&u.Scheme=="http"&&u.Host=="127.0.0.1")){r.Error="destination_blocked";return r;}var q=(HttpWebRequest)WebRequest.Create(u);q.Method="GET";q.AllowAutoRedirect=false;q.Timeout=deadline;q.ReadWriteTimeout=deadline;q.Accept="application/json";q.UserAgent="UsageGauge-ReadOnly-Probe";q.AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate;q.ServicePoint.Expect100Continue=false;if(headers!=null)foreach(var kv in headers)q.Headers[kv.Key]=kv.Value;
 using(var timer=new Timer(delegate(object unused){try{q.Abort();}catch{}},null,deadline,Timeout.Infinite)){try{HttpWebResponse resp=null;try{resp=(HttpWebResponse)q.GetResponse();}catch(WebException e){resp=e.Response as HttpWebResponse;if(resp==null)throw;}using(resp){r.Http=(int)resp.StatusCode;if(r.Http>=300&&r.Http<400){r.Error="redirect_rejected";return r;}if(r.Http!=200){r.Error=r.Http==401||r.Http==403?"login_rejected":r.Http==429?"rate_limited":"http_error";return r;}if(resp.ContentLength>Cap){r.Error="response_too_large";return r;}if(!(resp.ContentType??"").StartsWith("application/json",StringComparison.OrdinalIgnoreCase)){r.Error="unexpected_content_type";return r;}using(var s=resp.GetResponseStream())using(var m=new MemoryStream()){byte[] b=new byte[8192];int n;while((n=s.Read(b,0,b.Length))>0){if(m.Length+n>Cap){r.Error="response_too_large";return r;}m.Write(b,0,n);}r.Bytes=(int)m.Length;r.Body=new UTF8Encoding(false,true).GetString(m.ToArray());return r;}}}catch(WebException e){r.Error=e.Status==WebExceptionStatus.RequestCanceled||e.Status==WebExceptionStatus.Timeout?"deadline_exceeded":"network_error";}catch{r.Error="network_or_encoding_error";}}return r;}
 public static void Emit(object value){Console.WriteLine(J.Serialize(value));}
 static void Live(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;for(int i=0;i<3;i++){var r=new Dictionary<string,object>();r["service"]=new[]{"Codex","Claude","Grok"}[i];var w=Stopwatch.StartNew();var p=Process.GetCurrentProcess();var cpu=p.TotalProcessorTime;try{string path=i==0?Path.Combine(Home("CODEX_HOME",".codex"),"auth.json"):i==1?Path.Combine(Home("CLAUDE_CONFIG_DIR",".claude"),".credentials.json"):Path.Combine(Home("GROK_HOME",".grok"),"auth.json");var a=ReadAuth(path);r["credential_read_ms"]=w.ElapsedMilliseconds;string access=null;var h=new Dictionary<string,string>();if(i==0){var t=D(F(a,"tokens"));access=F(t,"access_token")as string;string acct=F(t,"account_id")as string;if(acct!=null)h["ChatGPT-Account-Id"]=acct;}else if(i==1){access=F(D(F(a,"claudeAiOauth")),"accessToken")as string;h["anthropic-beta"]="oauth-2025-04-20";}else{int found=0;foreach(var kv in a)if(kv.Key.StartsWith("https://auth.x.ai::",StringComparison.Ordinal)){found++;access=F(D(kv.Value),"key")as string;}if(found!=1)throw new Bad("ambiguous_or_missing_account");h["x-xai-token-auth"]="xai-grok-cli";}if(String.IsNullOrEmpty(access))throw new Bad("login_missing");h["Authorization"]="Bearer "+access;var networkWatch=Stopwatch.StartNew();var reply=Fetch(Urls[i],h,12000,false);r["network_ms"]=networkWatch.ElapsedMilliseconds;r["http"]=reply.Http;r["response_bytes"]=reply.Bytes;if(reply.Error!=null)r["status"]=reply.Error;else{r["data"]=i==0?Codex(reply.Body):i==1?Claude(reply.Body):Grok(reply.Body);r["status"]="ok";}h.Clear();access=null;}catch(Bad e){r["status"]=e.Message;}catch{r["status"]="unexpected_error_redacted";}p.Refresh();r["elapsed_ms"]=w.ElapsedMilliseconds;r["cpu_ms"]=(p.TotalProcessorTime-cpu).TotalMilliseconds;r["process_peak_working_set_bytes"]=p.PeakWorkingSet64;Emit(r);}}
 public static void Main(string[] args){try{Process.GetCurrentProcess().PriorityClass=ProcessPriorityClass.BelowNormal;if(args.Length==1&&args[0]=="--live")Live();else Emit(new{status="use_live_or_test_harness"});}catch{Emit(new{status="fatal_error_redacted"});Environment.ExitCode=1;}}
}